                        if isinstance(cc, list):
                            s = ' '.join([x.get('text','')[:150] for x in cc if isinstance(x,dict)])
                        else:
                            s = str(cc)[:150]
                        parts.append('TOOLRESULT:'+s)
                summary = ' | '.join(parts)
            print(i, ts, t.upper(), role, summary[:300])
        else:
            print(i, ts, t)
"

